/*
 * mappai-emoji-incorpora.js — le emoji locali da mettere DENTRO un documento (packet 0108).
 * GENERATO da tools/font/emoji-sottoinsieme.py — non modificare a mano.
 *
 * I glifi di public/fonts/MappAIEmoji.ttf (le 27 dell'identita + le emoji delle
 * pagine degli allievi e dei report), in WOFF, senza la tabella SVG: li legge
 * Electron, che disegna COLR v1. Serve perche il PDF di report e tessere nasce
 * da `data:`, dove un percorso al font non arriva, e Google Fonts non si usa piu.
 *
 * window.MappAIInc_emoji.facce(famiglia) → la @font-face con i byte incorporati.
 * In Node (il server LAN scrive i report su disco): require() dà lo stesso oggetto.
 */
(function () {
  "use strict";
  var B = "";
  var api = {
    facce: function (fam) {
      return "@font-face{font-family:'" + (fam || "MappAI Emoji") + "';src:url(data:font/woff;base64," + B +
        ") format('woff');font-weight:400;font-style:normal;font-display:block;}";
    }
  };
  if (typeof module === "object" && module.exports) module.exports = api;
  if (typeof window !== "undefined") window.MappAIInc_emoji = api;
})();
